{"kind":"tool","id":"yhZBOICrfiQ","toolName":"str_replace","input":{"path":"src/pages/Dashboard.css","replacements":[{"oldString":"/* --- "Photo" gradient text ----------------------------------------------
   ONLY the word "Photo" carries a looping blue→cyan gradient, clipped to
   its glyph shapes (background-clip: text). "Upload", the icon, border
   and button surface are untouched. The gradient layer is oversized
   (200%) and slides slowly; start/end stops match (blue at both ends),
   so the loop wraps with no visible reset. */
.dashboard-diagnosis-upload-text {
    color: inherit;
}

@supports ((-webkit-background-clip: text) or (background-clip: text)) {
    .dashboard-diagnosis-upload-photo {
        /* One periodic blue→cyan→blue tile; the layer is 200% wide so two
           full tiles exist. Animating position 0% → 100% slides exactly one
           tile — a true seamless loop — and because the layer REPEATS,
           every glyph stays covered at every instant (no cut-off text). */
        background-image: linear-gradient(
            90deg,
            #2f7fd1 0%,
            #22b8d4 25%,
            #2f7fd1 50%,
            #22b8d4 75%,
            #2f7fd1 100%
        );
        background-size: 200% 100%;
        background-repeat: repeat;
        background-position: 0% 0;
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
        animation: diagnosis-photo-gradient 5s linear infinite;
    }
}

@keyframes diagnosis-photo-gradient {
    from {
        background-position: 0% 0;
    }
    to {
        background-position: 100% 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .dashboard-diagnosis-upload-photo {
        animation: none;
    }
}","newString":"/* --- Upload Photo: ICON-ONLY looping motion -------------------------------
   The arrow rises toward the button's upper edge, fades out as it gets
   there, returns to its original spot and fades back in — a quiet
   "uploading" cue. ONLY the icon span animates (transform + opacity);
   the text, border, background and button geometry never move. The
   button clips its content (overflow: hidden on the --upload modifier),
   so the arrow can NEVER visually cross the border. */
.dashboard-diagnosis-btn--upload {
    overflow: hidden;
}

.dashboard-diagnosis-upload-icon {
    display: inline-flex;
    flex-shrink: 0;
    animation: diagnosis-upload-rise 3.2s ease-in-out infinite;
    will-change: transform, opacity;
}

@keyframes diagnosis-upload-rise {
    /* rest */
    0%,
    12% {
        transform: translateY(0);
        opacity: 1;
    }
    /* rise toward the button's upper area */
    48% {
        transform: translateY(-9px);
        opacity: 1;
    }
    /* faded out inside the button's upper portion (still clipped inside) */
    60% {
        transform: translateY(-13px);
        opacity: 0;
    }
    /* hold invisible at the top, then return */
    72% {
        transform: translateY(-13px);
        opacity: 0;
    }
    /* back at the original position, fading in */
    96%,
    100% {
        transform: translateY(0);
        opacity: 1;
    }
}

@media (prefers-reduced-motion: reduce) {
    .dashboard-diagnosis-upload-icon {
        animation: none;
    }
}","allowMultiple":false}]}}


