/* ==================== Profile floating panel ====================
   Opens under the small header avatar. The LARGE photo is the
   panel's dominant visual; everything else is quiet and clean.
   Uses the shared card tokens — no aurora, no neon, no glass. */
.header__avatar-wrap {
  position: relative;
  margin-left: 4px;
}

.header__avatar {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-full);
  background: var(--accent-soft);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: min(max(calc(12px * var(--ts-body, 1)), 9px), 24px);
  font-weight: 700;
  cursor: pointer;
  overflow: hidden;
  padding: 0;
  border: none;
}

.header__avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.profile-panel {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  width: 264px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
