}

.profile-panel__photo-edit {
  position: absolute;
  right: 8px;
  bottom: 8px;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  background: var(--bg-surface);
  color: var(--text-secondary);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-fast);
}

.profile-panel__photo-edit:hover {
  color: var(--text-primary);
  border-color: var(--text-secondary);
}

.profile-panel__error {
  margin: 8px 4px 0;
  font-size: 12px;
  color: var(--danger);
  text-align: left;
}

.profile-panel__name {
  margin: 14px 4px 2px;
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
}

.profile-panel__role-line {
  margin: 0 4px;
  font-size: 13px;
  color: var(--text-secondary);
}

.profile-panel__edit {
  margin-top: 12px;
