  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.profile-panel__edit:hover {
  background: var(--bg-hover);
}

.profile-panel__editor {
  margin: 12px 4px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
}

.profile-panel__field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--text-secondary);
}

.profile-panel__field input {
  padding: 8px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
}

.profile-panel__field input:focus {
  outline: none;
  border-color: var(--accent);
}

.profile-panel__field-label {
  font-size: 12px;
  color: var(--text-secondary);
}

.profile-panel__roles {
  display: flex;
  gap: 6px;
}

.profile-panel__role {
  flex: 1;
  padding: 8px 6px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.profile-panel__role--active {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--accent);
}

.profile-panel__actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.profile-panel__btn {
  flex: 1;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.profile-panel__btn--ghost {
  background: transparent;
  color: var(--text-secondary);
}

.profile-panel__btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

