{"kind":"tool","id":"1DwM_yQQJ3Y","toolName":"write_file","input":{"path":"src/components/auth/Auth.css","instructions":"Rewrite Auth.css with the fixed dark theme, cinematic scrim, and clean .auth-bg structure (remove the duplicated rule), keeping every other auth rule byte-identical.","content":"/* ============================================================
   Auth.css — Krisiveda authentication UI (Login + Signup).
   PRESENTATION ONLY: no auth logic anywhere in this file.
   Redesign surface — restyle freely without touching logic.

   Design language: static agricultural photo backdrop (pc.jpg on
   desktop, mob.jpg on mobile — BASE_URL-safe URLs passed as
   custom properties from AuthLayout.jsx) under a cinematic dark
   scrim, frosted glass card, premium typography. FIXED DARK
   PREMIUM THEME — the page never switches to light mode,
   regardless of the main website theme.
   ============================================================ */

/* ---------- page + photographic background ---------- */

.auth-page {
    position: relative;
    min-height: 100svh;
    display: flex;
    padding: 36px 16px;
    background-color: #04060c;
    background-image: var(--bg-desktop);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    color-scheme: dark;
    color: #eef2f8;
    font-family: var(--font-primary);
}

/* Deep cinematic scrim — above the photo, below the card
   (panel z-index 1). Transparent enough that the rice-field
   photo stays recognizable through it. Static — never animated. */
.auth-bg {
    position: absolute;
    inset: 0;
    background-color: rgba(6, 9, 16, 0.62);
    pointer-events: none;
    z-index: 0;
}

/* Subtle vignette for a richer, more cinematic base.
   No animation — the background stays completely static. */
.auth-bg::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(120% 85% at 50% 42%, transparent 42%, rgba(4, 6, 12, 0.55) 100%);
    pointer-events: none;
}

/* ---------- panel + brand ---------- */

.auth-panel {
    position: relative;
    z-index: 1;
    margin: auto; /* centers, but scrolls instead of clipping on short screens */
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    animation: authEnter 480ms cubic-bezier(0.22, 0.85, 0.35, 1) both;
}

@keyframes authEnter {
    from { opacity: 0; transform: translateY(14px) scale(0.985); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}

.auth-brand {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 22px;
    user-select: none;
}

.auth-brand__mark {
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    border-radius: 10px;
    background: linear-gradient(135deg, #4f46e5 0%, #2563eb 48%, #06b6d4 100%);
    color: #fff;
    box-shadow: 0 6px 18px rgba(37, 99, 235, 0.35);
}

.auth-brand__name {
    font-size: 16.5px;
    font-weight: 700;
    letter-spacing: 0.045em;
    color: #e8eefb;
}

/* ---------- glass card ---------- */

.auth-card {
    width: min(412px, 100%);
    background: linear-gradient(168deg, rgba(19, 26, 41, 0.74) 0%, rgba(10, 15, 26, 0.62) 100%);
    -webkit-backdrop-filter: blur(26px) saturate(140%);
    backdrop-filter: blur(26px) saturate(140%);
    border: 1px solid rgba(255, 255, 255, 0.09);
    border-radius: 26px;
    padding: 34px 32px 30px;
    box-sizing: border-box;
    box-shadow:
        0 26px 70px rgba(0, 0, 0, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.07);
}

.auth-card__head {
    margin-bottom: 22px;
    text-align: center;
}

.auth-card__title {
    margin: 0 0 7px;
    font-size: 27px;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #f4f7fc;
}

.auth-card__subtitle {
    margin: 0;
    font-size: 14px;
    color: #93a0b4;
}

/* ---------- alerts (error / success) ---------- */

.auth-alert {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    margin: 0 0 16px;
    padding: 11px 13px;
    border-radius: 12px;
    font-size: 13.5px;
    line-height: 1.5;
}

.auth-alert::before {
    content: "";
    flex-shrink: 0;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
    margin-top: 6px;
}

.auth-alert--error {
    background: rgba(248, 113, 113, 0.09);
    border: 1px solid rgba(248, 113, 113, 0.28);
    color: #fda4a4;
}

.auth-alert--success {
    background: rgba(74, 222, 128, 0.09);
    border: 1px solid rgba(74, 222, 128, 0.28);
    color: #8befae;
}

/* ---------- form + fields ---------- */

.auth-form {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.auth-field__label {
    display: block;
    margin-bottom: 7px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.01em;
    color: #c4cddb;
}

.auth-field__control {
    position: relative;
    display: flex;
    align-items: center;
}

.auth-field__icon {
    position: absolute;
    left: 14px;
    display: grid;
    place-items: center;
    color: #64748b;
    pointer-events: none;
}

.auth-field__input {
    width: 100%;
    height: 50px;
    box-sizing: border-box;
    padding: 0 14px;
    font-size: 14.5px;
    font-family: inherit;
    color: #eef2f8;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid rgba(255, 255, 255, 0.11);
    border-radius: 13px;
    outline: none;
    transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.auth-field__input::placeholder {
    color: #5d6b80;
}

.auth-field__input--icon {
    padding-left: 42px;
}

.auth-field__input--toggle {
    padding-right: 46px;
}

.auth-field__input:hover {
    border-color: rgba(255, 255, 255, 0.2);
}

.auth-field__input:focus {
    border-color: rgba(56, 189, 248, 0.65);
    background: rgba(255, 255, 255, 0.06);
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.14);
}

.auth-field__input--error {
    border-color: rgba(248, 113, 113, 0.6);
}

.auth-field__input--error:focus {
    box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.14);
}

.auth-field__toggle {
    position: absolute;
    right: 7px;
    display: grid;
    place-items: center;
    width: 34px;
    height: 34px;
    border-radius: 9px;
    background: none;
    border: none;
    color: #64748b;
    cursor: pointer;
    transition: color 150ms ease, background 150ms ease;
}

.auth-field__toggle:hover {
    color: #aab8ca;
    background: rgba(255, 255, 255, 0.06);
}

.auth-field__toggle:focus-visible {
    outline: 2px solid rgba(56, 189, 248, 0.6);
    outline-offset: 1px;
}

.auth-field__error {
    margin: 7px 0 0;
    font-size: 12.5px;
    color: #fda4a4;
}

/* ---------- buttons ---------- */

.auth-btn {
    width: 100%;
    height: 50px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    font-size: 14.5px;
    font-weight: 600;
    font-family: inherit;
    border-radius: 13px;
    border: 1px solid transparent;
    cursor: pointer;
    transition: filter 160ms ease, transform 160ms ease, background 160ms ease,
        border-color 160ms ease, box-shadow 160ms ease;
}

.auth-btn:disabled {
    opacity: 0.62;
    cursor: not-allowed;
}

.auth-btn:focus-visible {
    outline: 2px solid rgba(56, 189, 248, 0.7);
    outline-offset: 2px;
}

.auth-btn--primary {
    background: linear-gradient(135deg, #4f46e5 0%, #2563eb 46%, #06b6d4 100%);
    color: #fff;
    box-shadow: 0 10px 26px rgba(37, 99, 235, 0.3);
    margin-top: 4px;
}

.auth-btn--primary:not(:disabled):hover {
    filter: brightness(1.12);
    transform: translateY(-1px);
    box-shadow: 0 12px 30px rgba(37, 99, 235, 0.38);
}

.auth-btn--primary:not(:disabled):active {
    transform: translateY(0);
    filter: brightness(1.04);
}

.auth-btn--google {
    background: rgba(255, 255, 255, 0.05);
    color: #e8edf5;
    border-color: rgba(255, 255, 255, 0.13);
}

.auth-btn--google:not(:disabled):hover {
    background: rgba(255, 255, 255, 0.09);
    border-color: rgba(255, 255, 255, 0.24);
}

.auth-btn__google-icon {
    flex-shrink: 0;
}

.auth-btn__spinner {
    flex-shrink: 0;
    width: 15px;
    height: 15px;
    border-radius: 50%;
    border: 2px solid rgba(148, 163, 184, 0.4);
    border-top-color: currentColor;
    animation: authSpin 700ms linear infinite;
}

@keyframes authSpin {
    to { transform: rotate(360deg); }
}

/* ---------- divider + footer ---------- */

.auth-divider {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 20px 0;
    color: #7c8aa0;
    font-size: 11.5px;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

.auth-divider::before,
.auth-divider::after {
    content: "";
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.14), transparent);
}

.auth-divider::after {
    background: linear-gradient(90deg, rgba(255, 255, 255, 0.14), transparent);
}

.auth-card__footer {
    margin-top: 20px;
    text-align: center;
    font-size: 13.5px;
    color: #93a0b4;
}

.auth-card__footer a {
    color: #38bdf8;
    font-weight: 600;
    text-decoration: none;
    transition: color 150ms ease;
}

.auth-card__footer a:hover {
    color: #7dd3fc;
}

.auth-card__footer a:focus-visible {
    outline: 2px solid rgba(56, 189, 248, 0.6);
    outline-offset: 2px;
    border-radius: 4px;
}

/* ---------- mobile ---------- */

@media (max-width: 768px) {
    /* Mobile: automatically swap to the portrait mobile photo */
    .auth-page {
        background-image: var(--bg-mobile);
    }
}

@media (max-width: 480px) {
    .auth-page {
        padding: 28px 16px;
    }

    .auth-card {
        width: min(412px, calc(100vw - 32px));
        padding: 28px 22px 26px;
        border-radius: 22px;
    }

    .auth-card__title {
        font-size: 24px;
    }

    .auth-brand {
        margin-bottom: 18px;
    }
}
