```js
(() => {
  const row = document.querySelector('.profile-modal__confirm-actions');
  const [cancel, signout] = row.querySelectorAll('button');
  const measure = (btn) => {
    const br = btn.getBoundingClientRect();
    const range = document.createRange();
    range.selectNodeContents(btn);
    const cr = range.getBoundingClientRect();
    return {
      btnH: +br.height.toFixed(1),
      contentH: +cr.height.toFixed(1),
      vOff: +((cr.top + cr.height/2) - (br.top + br.height/2)).toFixed(2),
      hPadL: +(cr.left - br.left).toFixed(1),
      hPadR: +(br.right - cr.right).toFixed(1),
    };
  };
  const cs = getComputedStyle(row);
  return JSON.stringify({
    rowAlign: cs.alignItems, rowJustify: cs.justifyContent,
    cancel: measure(cancel), signout: measure(signout),
    heightsEqual: Math.abs(cancel.getBoundingClientRect().height - signout.getBoundingClientRect().height) < 0.5,
  });
})()
```

