```jsx
/* ================= Language floating menu (portal overlay) =================
   Rendered under document.body — completely outside the profile popup's
   overflow / transform / filter / backdrop-filter / stacking context, so
   the glass card can never clip it. Fixed-positioned from the Language
   button's live rect (below when it fits, above otherwise, viewport-
   clamped with internal scroll as a last resort) and kept glued to the
   button with a rAF tracking loop across resize/scroll/layout shifts. */
function LanguageMenu({ anchorRef, activeCode, onSelect, onClose }) {
  const menuRef = useRef(null);
  const posRef = useRef(null);

  useLayoutEffect(() => {
    const menu = menuRef.current;
    if (!menu) return undefined;
    let raf = 0;

    const place = () => {
      const btn = anchorRef.current;
      if (!btn || !btn.isConnected) return;
      const r = btn.getBoundingClientRect();
      const m = menu.getBoundingClientRect();
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const GAP = 8;
      const menuW = Math.max(m.width, 152);
      const left = Math.max(8, Math.min(r.left, vw - menuW - 8));
      const fullH = m.scrollHeight || m.height;
      let top, maxHeight;
      if (r.bottom + GAP + fullH <= vh) {
        top = r.bottom + GAP; maxHeight = fullH;
      } else if (r.top - GAP - fullH >= 0) {
        top = r.top - GAP - fullH; maxHeight = fullH;
      } else {
        top = Math.min(r.bottom + GAP, vh - 180); maxHeight = Math.max(140, vh - top - 8);
      }
      top = Math.max(8, Math.min(top, vh - Math.min(fullH, maxHeight) - 8));
      menu.style.left = `${Math.round(left)}px`;
      menu.style.top = `${Math.round(top)}px`;
      menu.style.maxHeight = `${Math.round(maxHeight)}px`;
    };

    place(); // before paint — no flicker
    const tick = () => { place(); raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);

    const onKey = (e) => { if (e.key === 'Escape') { e.stopPropagation(); onClose(); } };
    const onDown = (e) => {
      const t = e.target;
      if (menu.contains(t)) return;
      if (anchorRef.current && anchorRef.current.contains(t)) return; // button toggles itself
      onClose();
    };
    document.addEventListener('keydown', onKey, true);
    document.addEventListener('mousedown', onDown);
    return () => { cancelAnimationFrame(raf); document.removeEventListener('keydown', onKey, true); document.removeEventListener('mousedown', onDown); };
  }, [anchorRef, onClose]);

  const langs = [ ['en','English'], ['bn','বাংলা'], ... ];
  return createPortal(
    <div className="profile-modal__pref-menu profile-modal__langmenu" ref={menuRef} role="menu">
      {langs.map(([code, label]) => (
        <button key={code} role="menuitemradio" aria-checked={code === activeCode}
          className={`profile-modal__pref-option ${code === activeCode ? 'profile-modal__pref-option--active' : ''}`}
          onClick={() => onSelect(code)}>
          {label}
        </button>
      ))}
    </div>, document.body);
}
```

