{"kind":"tool","id":"-H_0JmdCkWY","toolName":"write_file","input":{"path":"src/components/layout/LanguageMenu.jsx","instructions":"Add a self-contained portal-based floating language menu component for the profile popup.","content":"import { useState, useRef, useEffect, useLayoutEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';

/* Floating language menu for the Profile Popup.
   Rendered through a portal under <body> with position: fixed, so it is
   completely independent of the popup's overflow, transforms, filters,
   backdrop-filters and stacking contexts — it cannot be clipped or
   buried by any of them. The popup merely passes the anchor (Language
   button) and the EXISTING language state/handlers. */

const GAP = 8;            // distance from the anchor button
const WIDTH = 160;        // fixed menu width
const FLIP_ESTIMATE = 200; // flip decision runs BEFORE first paint; the
                          // real height is measured right after render.

function LanguageMenu({ anchorRef, languages, activeCode, onSelect, onClose }) {
  const menuRef = useRef(null);
  const [pos, setPos] = useState(null); // {left, top} in viewport px

  /* Position: measure the anchor and the menu itself, then choose the
     placement with room for the FULL height; clamp inside the viewport.
     Runs before paint (useLayoutEffect) and continuously re-anchors via
     rAF while open — no stale coordinates after scroll/resize/reflow. */
  const place = useCallback(() => {
    const btn = anchorRef?.current;
    const menu = menuRef.current;
    if (!btn || !menu) return;
    const b = btn.getBoundingClientRect();
    if (b.width === 0 && b.height === 0) return; // anchor unmounted
    const h = menu.offsetHeight;
    const w = menu.offsetWidth || WIDTH;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let top;
    const roomBelow = vh - b.bottom - GAP >= h;
    const roomAbove = b.top - GAP >= h;
    if (roomBelow) top = b.bottom + GAP;
    else if (roomAbove) top = b.top - GAP - h; // flip only when it fully fits
    else top = Math.max(GAP, Math.min(b.bottom + GAP, vh - h - GAP)); // constrain + internal scroll

    const left = Math.max(GAP, Math.min(b.left, vw - w - GAP));
    setPos({ left, top });
  }, [anchorRef]);

  /* First placement: before paint, unpositioned → opacity 0 to avoid a
     flash at (0,0). Then keep re-anchoring every frame while open, so
     popup-internal scrolling, window resizes and mobile viewport changes
     (address bar) can never leave the menu detached from its button. */
  useLayoutEffect(() => {
    place();
    let raf;
    const tick = () => { place(); raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(only(raf));
    function only(x) { return x; }
  }, [place]);

  /* Safety net: re-place on the events rAF might miss between frames. */
  useEffect(() => {
    window.addEventListener('resize', place);
    document.addEventListener('scroll', place, true);
    return () => {
      window.removeEventListener('resize', place);
      document.removeEventListener('scroll', place, true);
    };
  }, [place]);

  /* Escape closes just the menu; outside mousedown closes it too. The
     menu stops propagation so the popup's own Escape handler (confirm →
     popup) doesn't also fire for the same keypress. */
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        onClose();
      }
    };
    document.addEventListener('keydown', onKey, true);
    const onDown = (e) => {
      const t = e.target;
      if (menuRef.current?.contains(t)) return;
      if (anchorRef?.current?.contains(t)) return;
      onClose();
      if (menuRef.current?.contains(anchorRef?.current ?? null) === false) return;
    };
    document.addEventListener('mousedown', onDown);
    return () => {
      document.removeEventListener('keydown', onKey, true);
      document.HeaderCleanup?.();
      document.removeEventListener('mousedown', onDown);
    };
  }, [onClose, anchorRef]);

  /* Close robustly on popup close/unmount of the anchor. */
  useEffect(() => {
    if (!anchorRef?.current) onClose();
  }, [anchorRef, onClose]);

  const unplaced = pos == null;
  return createPortal(
    <div
      className="profile-modal__pref-menu"
      ref={menuRef}
      style={pos ? { left: pos.left, top: pos.top } : { opacity: 0 }}
      role="menu"
      aria-label="Language"
   >
      {languages.map((lang) => (
        <button
          key={lang.code}
          type="button"
          role="menuitem"
          className={`profile-modal__pref-option ${lang.code === activeCode ? 'profile-modal__pref-option--only' : ''}${lang.code === activeCode ? ' profile-modal__pref-option--active' : ''}`}
          onClick={() => onSelect(lang.code)}
        className={`profile-modal__pref-option ${lang.code === activeCode ? 'profile-modal__pref-option--active' : ''}`}
        >
          {lang.native}
        </button>
        </button>
      ))}
    </div>,
    document.body
  );
}

export default LanguageMenu;
"}}


