          role="menuitem"
          className={`profile-modal__pref-option ${lang.code === activeCode ? 'profile-modal__pref-option--active' : ''}`}
          onClick={() => onSelect(lang.code)}
        >
          {lang.native}
        </button>
      ))}
    </div>,
    document.body
  );
}

