.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    /* Full dynamic-viewport height so the panel stays edge-to-edge even
       when mobile browser chrome resizes. top/bottom act as a fallback
       where dvh is unsupported. */
    height: 100dvh;
    width: var(--sidebar-width);
    /* SOLID near-black panel — opaque, no frost, no white inset */
    background: var(--sidebar-bg);
    border-right: 1px solid var(--glass-border);
    box-shadow: 8px 0 32px rgba(0, 0, 0, 0.25);
    display: flex;
    flex-direction: column;
    z-index: 100;
    transition: width var(--transition-base);
    overflow: hidden;
}

.sidebar--collapsed {
    width: 68px;
}

.sidebar__logo {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 20px 20px 16px;
    min-height: 64px;
}

/* Brand image (bit.png) beside the sidebar wordmark — displayed
   cleanly: natural aspect ratio, subtle rounding, no glow, no
   shadow, no animation. */
.sidebar__logo-icon {
    width: 26px;
    height: 26px;
    object-fit: contain;
    display: block;
    flex-shrink: 0;
    border-radius: 6px;
}

.sidebar__logo-text {
    font-size: max(min(calc(18px * var(--ts-mid, 1)), 26px), 10px);
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--text-primary);
    white-space: nowrap;
}

.sidebar__nav {
    flex: 1;
    /* Let the nav shrink below its content so it SCROLLS independently
       when items are tall, while the footer stays pinned at the bottom. */
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0 10px;
}

.sidebar__section {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sidebar__section-label {
    font-size: min(max(calc(12px * var(--ts-body, 1)), 9px), 24px);
