        90deg,
        var(--leaf-soft),
        rgba(111, 207, 142, 0.02)
    );
    border-left: 2px solid var(--leaf);
    box-shadow: inset 0 0 18px rgba(111, 207, 142, 0.07);
    color: var(--leaf);
    padding-left: 10px;
}

.sidebar__link--sub {
    font-size: min(max(calc(13px * var(--ts-body, 1)), 9px), 24px);
    padding: 7px 12px;
}

.sidebar--collapsed .sidebar__link {
    justify-content: center;
    padding: 10px;
}

.sidebar__divider {
    height: 1px;
    background: var(--border);
    margin: 8px 12px;
}

/* Pinned footer: the nav above grows/shrinks, this stays glued to the
   bottom edge. margin-top:auto guarantees it (belt-and-suspenders with
   the nav's flex:1), and safe-area padding keeps Settings off the screen
   edge / home-indicator. */
.sidebar__bottom {
    flex-shrink: 0;
    margin-top: auto;
    padding: 0 10px max(12px, env(safe-area-inset-bottom));
}

/* Settings section — the very last item, comfortably clear of the
   profile block above it. */
.sidebar__settings {
    margin-top: 6px;
}

.sidebar__user {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    margin-top: 4px;
}

/* Logged-out variant: the block is a sign-in LINK (no fake profile). */
.sidebar__user--signin {
    text-decoration: none;
    color: inherit;
    cursor: pointer;
}

.sidebar--collapsed .sidebar__user {
    justify-content: center;
    padding: 10px;
}

.sidebar__avatar {
    width: 32px;
    height: 32px;
    border-radius: var(--radius-full);
    background: var(--bg-elevated);
    border: 1px solid var(--border);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    flex-shrink: 0;
}

.sidebar__user-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.sidebar__user-name {
    font-size: min(max(calc(13px * var(--ts-body, 1)), 9px), 24px);
    font-weight: 600;
    color: var(--text-primary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.sidebar__user-role {
    font-size: min(max(calc(12px * var(--ts-body, 1)), 9px), 24px);
    color: var(--text-muted);
}

.sidebar__toggle {
    position: absolute;
    right: -12px;
    top: 50%;
    transform: translateY(-50%);
    width: 24px;
    height: 24px;
    border-radius: var(--radius-full);
    background: var(--bg-surface);
    border: 1px solid var(--border);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    cursor: pointer;
    transition: all var(--transition-fast);
    z-index: 10;
    opacity: 0;
}

.sidebar:hover .sidebar__toggle {
    opacity: 1;
}

.sidebar__toggle:hover {
    background: var(--bg-elevated);
    color: var(--text-primary);
}

@media (max-width: 1024px) {
    .sidebar {
        display: none;
    }
}
