{"kind":"tool","id":"MIglxxpfky8","toolName":"write_file","input":{"path":"src/components/layout/Sidebar.jsx","instructions":"Remove the desktop sidebar bottom profile row (avatar + name/role or login link) but keep Settings pinned to the bottom. This rewrite preserves the rest of the file exactly and only changes the sidebar__bottom block.","content":"import { NavLink, useLocation } from 'react-router-dom';
import { useLanguage } from '../../hooks/useLanguage';
import { useAuth } from '../../hooks/useAuth';
import { profileNameKeyFor, profileRoleKeyFor, lsGet } from '../../lib/profileStore';
import { resolveActiveSection } from '../../lib/activeSection';
import {
  LayoutDashboard, Tractor, Leaf, TrendingUp,
  BarChart3, Stethoscope,
  Bug, Beaker, Wallet, Store, Settings, User, ChevronLeft, ChevronRight,
} from 'lucide-react';
import { useState } from 'react';
import './Sidebar.css';

// Shared with MobileDrawer so both navigations always stay in sync
export const navItems = [
  { path: '/', icon: LayoutDashboard, labelKey: 'nav.overview' },
  { path: '/farm', icon: Tractor, labelKey: 'nav.myFarm' },
  { path: '/crops', icon: Leaf, labelKey: 'nav.crops' },
  { path: '/improve', icon: TrendingUp, labelKey: 'nav.improve' },
  { path: '/insights', icon: BarChart3, labelKey: 'nav.insights' },
  { path: '/ai-doctor', icon: Stethoscope, labelKey: 'nav.aiDoctor' },
];

export const subItems = [
  { path: '/disease', icon: Bug, labelKey: 'nav.disease' },
  { path: '/fertilizer', icon: Beaker, labelKey: 'nav.fertilizer' },
  { path: '/finance', icon: Wallet, labelKey: 'nav.finance' },
  { path: '/market', icon: Store, labelKey: 'nav.market' },
];

export const bottomItems = [
  { path: '/settings', icon: Settings, labelKey: 'nav.settings' },
];

export default function Sidebar() {
  const { t } = useLanguage();
  const location = useLocation();
  /* Route-derived section (activeSection.js): /crops + /crops/:id keep
     MY FARM highlighted — NavLink alone can't match those routes. */
  const activeSection = resolveActiveSection(location.pathname);
  const [collapsed, setCollapsed] = useState(false);
  // Identity block is driven by the REAL Supabase session only: a user
  // block appears ONLY when authenticated. Skipped/logged-out visitors
  // get a plain sign-in link — never a fabricated profile (spec §4/§6).
  const { user } = useAuth();
  // USER-SCOPED reads (profileStore.js): only the signed-in user's OWN
  // name/role keys are consulted — never a shared key another account
  // could have written.
  const storedName = (user?.id && lsGet(profileNameKeyFor(user.id))) || '';
  const storedRole = (user?.id && lsGet(profileRoleKeyFor(user.id))) || '';
  // Only a real account's information is shown: profile name, else the
  // real account's email prefix. Role only if the user actually picked one.
  const displayName =
    user?.name || storedName || (user?.email ? user.email.split('@')[0] : '');
  const displayRole = storedRole
    ? storedRole === 'Business Man'
      ? t('common.profile.businessMan')
      : t('common.profile.farmer')
    : '';

  return (
    <aside className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
      <div className="sidebar__logo">
        <img
          src={`${import.meta.env.BASE_URL}bit.png`}
          alt="Krisiveda"
          className="sidebar__logo-icon"
        />
        {!collapsed && <span className="sidebar__logo-text">Krisiveda</span>}
      </div>

      <nav className="sidebar__nav">
        <div className="sidebar__section">
          {navItems.map((item) => (
            <NavLink
              key={item.path}
              to={item.path}
            className={({ isActive }) =>
              `sidebar__link ${
                isActive || activeSection === item.path
                  ? 'sidebar__link--active'
                  : ''
              }`
            }
            end={item.path === '/'}
              title={collapsed ? t(item.labelKey) : undefined}
            >
              <item.icon size={20} />
              {!collapsed && <span>{t(item.labelKey)}</span>}
            </NavLink>
          ))}
        </div>

        <div className="sidebar__divider" />

        <div className="sidebar__section">
          {!collapsed && <div className="sidebar__section-label">{t('common.tools')}</div>}
          {subItems.map((item) => (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) =>
                `sidebar__link sidebar__link--sub ${isActive ? 'sidebar__link--active' : ''}`
              }
              title={collapsed ? t(item.labelKey) : undefined}
            >
              <item.icon size={18} />
              {!collapsed && <span>{t(item.labelKey)}</span>}
            </NavLink>
          ))}
        </div>
      </nav>

      {/* Desktop sidebar no longer shows the bottom profile/name row.
          The top-right header avatar and all account functionality
          remain intact; only this sidebar footer block is removed. */}
      <div className="sidebar__bottom">
        <div className="sidebar__settings">
          {bottomItems.map((item) => (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) =>
                `sidebar__link ${isActive ? 'sidebar__link--active' : ''}`
              }
              title={collapsed ? t(item.labelKey) : undefined}
            >
              <item.icon size={20} />
              {!collapsed && <span>{t(item.labelKey)}</span>}
            </NavLink>
          ))}
        </div>
      </div>

      <button
        className="sidebar__toggle"
        onClick={() => setCollapsed(!collapsed)}
        aria-label={collapsed ? t('common.expandSidebar') : t('common.collapseSidebar')}
      >
        {collapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
      </button>
    </aside>
  );
}
"}}


