import { mobileNavItems } from './MobileNavigation';
import { resolveSectionForPath } from '../../lib/activeSection';
import './MobileDrawer.css';

/**
 * Left-side slide-out navigation drawer (≤1024px).
 * Shows everything EXCEPT the five items already reachable from the
 * mobile bottom navigation bar (Overview, My Farm, AI Doctor, Improve
 * Yield, Insights) — so no destination is listed twice on mobile.
 */
const bottomNavPaths = new Set(mobileNavItems.map((item) => item.path));

export default function MobileDrawer({ open, onClose }) {
    const { t } = useLanguage();
    const location = useLocation();

    const drawerNavItems = navItems.filter((item) => !bottomNavPaths.has(item.path));

    /* Same route-derived section logic as the bottom bar (activeSection.js):
       each drawer link lights up from its OWN route match; the resolver
       adds nothing extra for sidebar-only features (they map to null in
       the bottom bar). */
    const activeSection = resolveSectionForPath(location.pathname);

    /** NavLink-style class fn for one item: green when the link's own
        route is active OR when the current route resolves to its section. */
    const linkClassFor = (itemPath) =>
        ({ isActive }) =>
            `mobile-drawer__link ${
                isActive || activeSection === itemPath
                    ? 'mobile-drawer__link--active'
                    : ''
            }`;

    const subLinkClassFor = (itemPath) =>
        ({ isActive }) =>
            `mobile-drawer__link mobile-drawer__link--sub ${
                isActive || activeSection === itemPath
                    ? 'mobile-drawer__link--active'
                    : ''
            }`;

    return (
        <>
            <div
                className={`mobile-drawer__overlay ${open ? 'mobile-drawer__overlay--open' : ''}`}
                onClick={onClose}
                aria-hidden="true"
            />
            <aside
                className={`mobile-drawer ${open ? 'mobile-drawer--open' : ''}`}
                role="dialog"
                aria-modal="true"
                aria-label={t("common.navigation")}
            >
                <div className="mobile-drawer__logo">
                    <img
                        src={`${import.meta.env.BASE_URL}bit.png`}
                        alt="Krisiveda"
                        className="mobile-drawer__logo-icon"
                    />
                    <span className="mobile-drawer__logo-text">Krisiveda</span>
                    <button
                        className="mobile-drawer__close"
                        onClick={onClose}
                        aria-label={t("common.close")}
                    >
                        <X size={18} />
                    </button>
                </div>

                <nav className="mobile-drawer__nav">
                    <div className="mobile-drawer__section">
                        {drawerNavItems.map((item) => (
                            <NavLink
                                key={item.path}
                                to={item.path}
                                className={linkClassFor(item.path)}
                                end={item.path === '/'}
                                onClick={onClose}
                            >
                                <item.icon size={20} />
                                <span>{t(item.labelKey)}</span>
                            </NavLink>
                        ))}
                    </div>

                    <div className="mobile-drawer__section">
                        {subItems.map((item) => (
                            <NavLink
                                key={item.path}
                                to={item.path}
                                className={subLinkClassFor(item.path)}
                                onClick={onClose}
                            >
                                <item.icon size={18} />
                                <span>{t(item.labelKey)}</span>
                            </NavLink>
                        ))}
                    </div>
                </nav>

                {/* Settings pinned to the drawer's bottom edge — a separate
                    section, clear of the scrolling nav above. */}
                <div className="mobile-drawer__footer">
                    <div className="mobile-drawer__divider" />
                    <div className="mobile-drawer__section">
                        {bottomItems.map((item) => (
                            <NavLink
                                key={item.path}
                                to={item.path}
                                className={subLinkClassFor(item.path)}
                                onClick={onClose}
                            >
                                <item.icon size={18} />
                                <span>{t(item.labelKey)}</span>
                            </NavLink>
                        ))}
                    </div>
                </div>
            </aside>
        </>
    );
}
