    box-shadow: 8px 0 32px rgba(0, 0, 0, 0.25);
    display: flex;
    flex-direction: column;
    z-index: 100;
    transition: width var(--transition-base);
    overflow: hidden;
}

.sidebar--collapsed {
    width: 68px;
}

.sidebar__logo {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 20px 20px 16px;
    min-height: 64px;
}

/* Brand image (bit.png) beside the sidebar wordmark — displayed
   cleanly: natural aspect ratio, subtle rounding, no glow, no
   shadow, no animation. */
.sidebar__logo-icon {
    width: 26px;
    height: 26px;
    object-fit: contain;
    display: block;
    flex-shrink: 0;
    border-radius: 6px;
}

.sidebar__logo-text {
    font-size: max(min(calc(18px * var(--ts-mid, 1)), 26px), 10px);
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--text-primary);
    white-space: nowrap;
}

.sidebar__nav {
    flex: 1;
    /* Let the nav shrink below its content so it SCROLLS independently
       when items are tall, while the footer stays pinned at the bottom. */
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0 10px;
}

.sidebar__section {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sidebar__section-label {
    font-size: min(max(calc(12px * var(--ts-body, 1)), 9px), 24px);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    padding: 8px 12px 6px;
}

.sidebar__link {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 9px 12px;
    border-radius: var(--radius-md);
    font-size: min(max(calc(14px * var(--ts-body, 1)), 9px), 24px);
    font-weight: 500;
    color: var(--text-secondary);
    transition: all var(--transition-fast);
    white-space: nowrap;
    text-decoration: none;
}

.sidebar__link:hover {
    background: var(--sidebar-hover);
    color: var(--text-primary);
}

.sidebar__link--active {
    /* Soft illuminated pill rather than a solid block */
    background: linear-gradient(
        90deg,
        var(--leaf-soft),
        rgba(111, 207, 142, 0.02)
    );
    border-left: 2px solid var(--leaf);
    box-shadow: inset 0 0 18px rgba(111, 207, 142, 0.07);
    color: var(--leaf);
    padding-left: 10px;
}

.sidebar__link--sub {
    font-size: min(max(calc(13px * var(--ts-body, 1)), 9px), 24px);
    padding: 7px 12px;
}

.sidebar--collapsed .sidebar__link {
    justify-content: center;
    padding: 10px;
}

